def merge_range_pairs(prs):
    """Takes in a list of pairs specifying ranges and returns a sorted list of merged, sorted ranges."""
    prs = sorted(prs)
    merged = []
    for pr in prs:
        if not merged or merged[-1][1] < pr[0]:
            merged.append(pr)
        else:
            merged[-1][1] = max(merged[-1][1], pr[1])
    return merged

